// Gives the scenario its audio paths from the list of message ids that have a recorded clip.
// The list is generated by tools/gen-voice.mjs (single-source.voice.ts); scenario content never names a clip by hand.

interface CueLike {
  kind: string;
  id?: string;
}

/** The parts of a scenario that carry cues. Both the raw scenario object and a parsed Scenario fit. */
interface VoiceableScenario {
  eventSets: readonly { startCues: readonly CueLike[]; rules: readonly { cues: readonly CueLike[] }[] }[];
  softTimeout: { promptCue: CueLike };
}

/**
 * Returns a deep copy in which every message cue (Event Set start cues, rule cues, the soft-timeout prompt) whose id is in
 * `voicedIds` has `audio: '/audio/voice/<id>.mp3'`. Other cues are untouched; ids that are not messages are ignored.
 * The same id always gets the same path, so a message sent twice still satisfies the contract's reuse check.
 */
export function withVoice<T extends VoiceableScenario>(raw: T, voicedIds: readonly string[]): T {
  const voiced = new Set(voicedIds);
  const copy = structuredClone(raw);
  const apply = (cue: CueLike): void => {
    if (cue.kind === 'message' && cue.id !== undefined && voiced.has(cue.id)) {
      (cue as CueLike & { audio?: string }).audio = `/audio/voice/${cue.id}.mp3`;
    }
  };
  for (const set of copy.eventSets) {
    set.startCues.forEach(apply);
    for (const rule of set.rules) rule.cues.forEach(apply);
  }
  apply(copy.softTimeout.promptCue);
  return copy;
}
